class A:
    def falar(self):
        return "A"

class B(A):
    def falar(self):
        return "B" + super().falar()

class C(A):
    def falar(self):
        return "C" + super().falar()

class D(B, C):
    def falar(self):
        return "D" + super().falar()

print(D().falar())
